var $ = function(s){ return document.querySelector(s); };
var reduce = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;
function rand(a,b){ return a+Math.random()*(b-a); }
function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
function lerp(a,b,t){ return a+(b-a)*t; }
function pick(a){ return a[Math.floor(Math.random()*a.length)]; }
function ease(t){ t=clamp(t,0,1); return t<.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2; }
function easeIn(t){ t=clamp(t,0,1); return t*t*t; }
function easeOut(t){ t=clamp(t,0,1); return 1-Math.pow(1-t,3); }
function easeOutBack(t){ t=clamp(t,0,1); var c1=1.5,c3=c1+1; return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2); }
function bell(p){ return Math.sin(Math.PI*clamp(p,0,1)); }
function env(p,a,r){ return p<a ? ease(p/a) : (p>1-r ? ease((1-p)/r) : 1); }
function esc(s){ return String(s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function icon(k,cls){
  var svg=ICONS[k]||"";
  if(k.charAt(0)==="o") return '<span class="oi'+(cls?" "+cls:"")+'" aria-hidden="true">'+svg+'</span>';
  return svg.replace("<svg ",'<svg class="ic'+(cls?" "+cls:"")+'" ');
}
function oi(mod){ return icon("o_"+mod); }
function svgImage(k,color){
  var svg=(ICONS[k]||"").replace(/currentColor/g,color||"#3167CA");
  if(svg.indexOf("xmlns")<0) svg=svg.replace("<svg ",'<svg xmlns="http://www.w3.org/2000/svg" ');
  svg=svg.replace("<svg ",'<svg width="256" height="256" ');
  var img=new Image(); img.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg); return img;
}

