/* ---------------- fuzzy matching, ported from the site assistant ---------------- */
function norm(s){ return (s||'').toLowerCase().replace(/[‘’'`]/g,'').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim(); }
function toks(s){ return norm(s).split(' ').filter(Boolean); }
function stem(w){ return w.replace(/(ations|ation|ings|ing|ies|ied|ers|er|ed|es|s)$/,'').replace(/(.)\1$/,'$1'); }
function phon(w){
  w=(w||'').replace(/[^a-z]/g,''); if(!w) return '';
  var first=w.charAt(0);
  var rest=w.slice(1).replace(/ph/g,'f').replace(/gh/g,'').replace(/ck/g,'k').replace(/qu/g,'k').replace(/q/g,'k')
    .replace(/[aeiouyhw]/g,'').replace(/c/g,'k').replace(/z/g,'s').replace(/v/g,'f').replace(/x/g,'ks').replace(/j/g,'g').replace(/(.)\1+/g,'$1');
  return (first+rest).replace(/(.)\1+/g,'$1');
}
function lev(a,b){
  var m=a.length,n=b.length; if(!m) return n; if(!n) return m;
  if(Math.abs(m-n)>4) return Math.abs(m-n)+2;
  var d=[],i,j; for(j=0;j<=n;j++) d[j]=j;
  for(i=1;i<=m;i++){ var prev=d[0]; d[0]=i; for(j=1;j<=n;j++){ var t=d[j]; d[j]=Math.min(d[j]+1,d[j-1]+1,prev+(a.charAt(i-1)===b.charAt(j-1)?0:1)); prev=t; } }
  return d[n];
}
function tol(len){ return len<=3?0:len<=7?1:len<=10?2:3; }
function wordMatch(tok,kw){
  if(tok===kw) return 1;
  if(tok.length>=4 && kw.indexOf(tok)===0) return .9;
  if(kw.length>=4 && tok.indexOf(kw)===0) return .9;
  var s1=stem(tok), s2=stem(kw); if(s1 && s1===s2) return .88;
  var d=lev(tok,kw); if(d<=tol(Math.max(tok.length,kw.length))) return 1-d*.16;
  if(tok.length>=4 && kw.length>=4){ var pt=phon(tok); if(pt.length>=4 && pt===phon(kw)) return .5; }
  return 0;
}
function bestSingle(tok,singles){ var best=0; for(var j=0;j<singles.length;j++){ var m=wordMatch(tok,singles[j]); if(m>best){ best=m; if(best>=1) break; } } return best; }
/* generic words (odoo, technext, erp...) count half when the question also has a real topic word,
   so "is odoo expensive" reaches pricing instead of tying with What is Odoo */
var GENERIC = { odoo:1, odooo:1, oodo:1, technext:1, erp:1, system:1, software:1, company:1 };
var STOPW = { the:1, a:1, an:1, do:1, does:1, you:1, your:1, we:1, i:1, is:1, are:1, can:1, for:1, to:1, of:1, and:1, or:1, my:1, our:1, us:1, me:1, it:1, in:1, on:1, with:1, what:1, whats:1, how:1, have:1, has:1, be:1, there:1, any:1, about:1, tell:1, please:1, ah:1, la:1, lah:1 };
function scoreEntry(k,qtoks,qnorm){
  var content=0; for(var c=0;c<qtoks.length;c++){ if(qtoks[c].length>=3 && !GENERIC[qtoks[c]] && !STOPW[qtoks[c]]) content++; }
  if(!k._sing){ k._sing=[]; k._phr=[]; k.kw.forEach(function(w){ var n=norm(w); if(!n) return; (n.indexOf(' ')>-1?k._phr:k._sing).push(n); }); }
  var s=0,i,j,p;
  for(i=0;i<k._phr.length;i++){
    var ph=k._phr[i];
    if(qnorm.indexOf(ph)>-1){ s+=2; continue; }
    var parts=ph.split(' '), tot=0, ok=true, best;
    for(p=0;p<parts.length;p++){ best=0; for(j=0;j<qtoks.length;j++){ var m=wordMatch(qtoks[j],parts[p]); if(m>best) best=m; } if(best<.6){ ok=false; break; } tot+=best; }
    if(ok) s+=(tot/parts.length)*1.6;
  }
  for(i=0;i<qtoks.length;i++){ if(qtoks[i].length<2) continue; var b=bestSingle(qtoks[i],k._sing); if(b>0) s+=b*(GENERIC[qtoks[i]] && content ? 1 : 2); }
  return s;
}
function cleanTitle(t){ return (t||'').split(/\s[—|·]\s/)[0].replace(/\s*[|·]\s*TechNext\s*$/i,'').trim(); }
function searchSite(qtoks){
  if(!SITE.length || !qtoks.length) return null;
  var scored=SITE.map(function(p){
    if(!p._h) p._h=toks((p.t||'')+' '+(p.d||''));
    var tt=p._tt||(p._tt=toks(p.t||'')), sc=0;
    qtoks.forEach(function(tok){
      if(tok.length<3) return;
      var best=0,k; for(k=0;k<p._h.length;k++){ var s=wordMatch(tok,p._h[k]); if(s>best) best=s; }
      var inTitle=0; for(k=0;k<tt.length;k++){ var s2=wordMatch(tok,tt[k]); if(s2>inTitle) inTitle=s2; }
      sc+=best+inTitle*.6;
    });
    return { p:p, score:sc };
  }).sort(function(a,b){ return b.score-a.score; });
  var top=scored[0]; if(!top || top.score<1.3) return null;
  var floor=Math.max(1.7,top.score*.75);
  return [top.p].concat(scored.slice(1).filter(function(x){ return x.score>=floor; }).slice(0,2).map(function(x){ return x.p; }));
}
function bestOf(list,qt,qn){ var best=null,score=0; list.forEach(function(k){ var s=scoreEntry(k,qt,qn); if(s>score){ score=s; best=k; } }); return { k:best, s:score }; }
var TOUR_KB = Object.keys(TOUR_KW).map(function(id){ return { id:id, kw:TOUR_KW[id] }; });
function understand(text){
  var qn=norm(text), qt=toks(text); if(!qt.length) return null;
  var tour=bestOf(TOUR_KB,qt,qn), kb=bestOf(KB,qt,qn);
  if(tour.k && tour.s>=1.1 && tour.s>=kb.s) return { type:'tour', q:byId(tour.k.id) };
  if(kb.k && kb.s>=1.1) return { type:'kb', k:kb.k };
  var pages=searchSite(qt); if(pages) return { type:'site', pages:pages };
  if(kb.k && kb.s>=.7) return { type:'kb', k:kb.k };
  if(tour.k && tour.s>=.7) return { type:'tour', q:byId(tour.k.id) };
  return null;
}

