/* critically damped spring, stable at any frame rate */
function Spring(freq,damp){ this.w=2*Math.PI*freq; this.z=damp==null?1:damp; this.x=0; this.v=0; }
Spring.prototype.step=function(target,dt){
  var n=Math.max(1,Math.ceil(dt/.008)), h=dt/n, w=this.w, z=this.z;
  for(var i=0;i<n;i++){ var a=-w*w*(this.x-target)-2*z*w*this.v; this.v+=a*h; this.x+=this.v*h; }
  return this.x;
};

