    presentBoth:{ dur:2.2, fn:function(p,O){ var e=env(p,.2,.25); O.hLx-=.34*e; O.hLy+=.44*e; O.hRx+=.34*e; O.hRy+=.44*e; O.hLz+=.2*e; O.hRz+=.2*e; O.tilt+=.06*e; O.nod-=.05*e; } },
