      o.g.visible=o.k>.001; o.label.on=orbState.on && o.k>.6;
      if(!o.g.visible) return;
      o.a+=dt*.22;
      var fk=o.f.step(orbState.focus===o.s.id?1:0,dt);
      tmp2.set(Math.sin(o.a)*2.05,1.55+Math.sin(time*1.2+i*2)*.07,Math.cos(o.a)*2.05).lerp(ORB_FOCUS,clamp(fk,0,1.1));
