  /* ---- order flow */
  var flow=null, flowState={ on:false, t0:0, step:0, from:0, hopT0:-9, all:false };
  function tileTex(i,active){
    var tex=canvasTex(512,512,function(){});
    var img=svgImage(FLOW[i].icon);
    function draw(g){
      rr(g,14,14,484,484,84); g.fillStyle=active?"#3167ca":"#ffffff"; g.fill();
      if(active){ rr(g,108,108,296,296,72); g.fillStyle="#ffffff"; g.fill(); }
      if(img.complete && img.naturalWidth) g.drawImage(img,146,146,220,220);
    }
    redraw(tex,draw); img.onload=function(){ redraw(tex,draw); };
    return tex;
  }
