    FLOW.forEach(function(f,i){
      var a=(-60+i*30)*Math.PI/180, g=new THREE.Group();
      g.position.set(RR*Math.sin(a),0,RR*Math.cos(a)); g.visible=false; scene.add(g);
      g.add(mesh(geo,M.shell));
      g.add(softDisc(1.9,"rgba(24,40,90,.3)","rgba(24,40,90,.1)",.004));
      var texN=tileTex(i,false), texA=tileTex(i,true);
      var top=new THREE.Mesh(new THREE.PlaneGeometry(.92,.92), new THREE.MeshBasicMaterial({ map:texN, transparent:true, toneMapped:false, polygonOffset:true, polygonOffsetFactor:-2 }));
      top.rotation.x=-Math.PI/2; top.position.y=.097; top.userData.noGlow=true; g.add(top);
      var ring=glowMesh(new THREE.RingGeometry(.7,.76,72),new THREE.MeshBasicMaterial({ color:0x5d8ff0, transparent:true, opacity:0, toneMapped:false, depthWrite:false }));
      ring.rotation.x=-Math.PI/2; ring.position.y=.008; g.add(ring);
      var el=document.createElement("div"); el.className="tag3";
      el.innerHTML='<span class="n">'+(i+1)+'</span><span>'+esc(f.k)+'</span><small>'+esc(f.app.replace("Odoo ",""))+'</small>';
      var label=pin(el,g,new THREE.Vector3(0,.02,.74));
      tiles.push({ g:g, top:top, texN:texN, texA:texA, ring:ring, label:label, k:new Spring(2.2,.7) });
    });
    var pts=[]; for(var k=0;k<=48;k++){ var a=(-60+k*120/48)*Math.PI/180; pts.push(new THREE.Vector3(RR*Math.sin(a),.03,RR*Math.cos(a))); }
    var curve=new THREE.CatmullRomCurve3(pts);
    var tubeA=new THREE.Mesh(new THREE.TubeGeometry(curve,96,.014,8,false), new THREE.MeshBasicMaterial({ color:0xffffff, transparent:true, opacity:.8, toneMapped:false }));
    tubeA.userData.noGlow=true;
