    tubeA.visible=tubeB.visible=false; scene.add(tubeA); scene.add(tubeB);
    var token=new THREE.Group(); token.visible=false; scene.add(token);
    var box=mesh(new THREE.BoxGeometry(.24,.24,.24), new THREE.MeshPhysicalMaterial({ color:0x3167ca, roughness:.3, clearcoat:1, clearcoatRoughness:.1, emissive:0x1e4691, emissiveIntensity:.3 }));
    box.position.y=.12; token.add(box);
