    ray.setFromCamera(ndcOf(e.clientX,e.clientY),camera);
    if(orbs && orbState.on){
      var hit=ray.intersectObjects(orbs.map(function(o){ return o.sph; }));
      if(hit.length && api.onOrb){ api.onOrb(hit[0].object.userData.orb); return; }
    }
    if(PL.state!=="home" && ray.intersectObject(planeMesh).length){ PL.loopT0=time; play("clap"); setExpr("happy",1.2); Snd.play("whee"); word("WOOO!"); return; }
    if(ray.intersectObjects(botParts).length){ if(api.onBot) api.onBot(); return; }
    if(Places.tap(ray)) return;
