    bGeo.setAttribute("position",new THREE.BufferAttribute(bPos,3)); bGeo.setAttribute("color",new THREE.BufferAttribute(bCol,3)); bGeo.setAttribute("aSize",new THREE.BufferAttribute(bSize,1));
    var ptVS="attribute float aSize; attribute vec3 color; varying vec3 vC; varying float vA; uniform float uPR; void main(){ vC=color; vec4 mv=modelViewMatrix*vec4(position,1.0); vA=aSize>0.0?1.0:0.0; gl_PointSize=aSize*uPR*(260.0/-mv.z); gl_Position=projectionMatrix*mv; }";
