          pts.material.uniforms.uShape.value=mode==="rain"?1:(mode==="confetti"?2:0);
          pts.material.blending=(mode==="snow"||mode==="confetti"||mode==="petals"||mode==="rain")?THREE.NormalBlending:THREE.AdditiveBlending; pts.material.needsUpdate=true;
          pts.userData.glow=(mode==="stars"||mode==="fireflies"||mode==="data"||mode==="sparks");
          for(var i=0;i<N;i++){
            var col=new THREE.Color(colors[i%colors.length]); c[i*3]=col.r; c[i*3+1]=col.g; c[i*3+2]=col.b;
            var r=Math.random(), a=Math.random()*Math.PI*2;
            if(mode==="stars"){ var el=.15+Math.random()*.85, d=34; p[i*3]=Math.cos(a)*d*Math.cos(el*1.2); p[i*3+1]=1+Math.sin(el*1.2)*d*.6; p[i*3+2]=-Math.abs(Math.sin(a))*d-6; }
            else { p[i*3]=(Math.random()-.5)*22; p[i*3+1]=Math.random()*11; p[i*3+2]=(Math.random()-.5)*16-3; }
          }
