function smallMatch(cleaned){
  var qt=toks(cleaned), qn=norm(cleaned); if(!qt.length) return null;
  var best=null, score=0; SMALL.forEach(function(s){ var sc=scoreEntry(s,qt,qn); if(sc>score){ score=sc; best=s; } });
  if(!best) return null;
  var need=best.short?1.6:1.1;
  if(best.short && qt.length>4) return null;
  return score>=need ? { s:best, score:score } : null;
}

/* place + play commands: "take me to singapore", "make it snow", "lights off", "party" */
var PLACE_WORDS = { studio:['studio','home','back home','go home','headquarters studio'], singapore:['singapore','marina bay','sg','merlion'], philippines:['philippines','beach','manila','taguig','sunset','island','boracay','tropical'],
  vietnam:['vietnam','lantern','lanterns','hoi an','ho chi minh','river'], space:['space','outer space','moon','planet','stars','galaxy','rocket','universe','zero gravity'], snow:['snow peak','mountain','mountains','winter','snowy','north pole','ski'],
  datacenter:['data center','datacenter','server','servers','server room','cloud','matrix','cyber'] };
var GO_VERBS = /\b(go|take|bring|visit|teleport|travel|fly|show|switch|change|move|let s go|lets go|beam|warp|transport)\b/;
function command(cleaned){
  var c=' '+cleaned+' ';
  if(/\b(make it|let it|start|turn on)? ?(snow|snowing)\b/.test(c) && !/snow peak|mountain/.test(c) && /\b(make|let|start|turn|it)\b/.test(c)) return { kind:'weather', v:'snow' };
  if(/\b(make it rain|rain|raining|rainy)\b/.test(c) && /\b(make|let|start|it|rain)\b/.test(c) && !/price|cost/.test(c)) return { kind:'weather', v:'rain' };
  if(/\b(petals|flowers|sakura|blossom)\b/.test(c)) return { kind:'weather', v:'petals' };
  if(/\b(stop|clear|no more) (the )?(rain|snow|weather|petals|confetti)\b|\bclear sky\b|\bsunny\b/.test(c)) return { kind:'weather', v:'none' };
  if(/\b(lights? off|turn off the lights?|night ?time|night mode|make it dark|go dark|dark mode)\b/.test(c)) return { kind:'night', v:true };
  if(/\b(lights? on|turn on the lights?|day ?time|day mode|make it bright|morning mode)\b/.test(c)) return { kind:'night', v:false };
  if(/\b(party|disco|celebrate|confetti|fiesta)\b/.test(c)) return { kind:'party' };
  if(/\b(dance|dancing|bust a move|boogie)\b/.test(c)) return { kind:'dance' };
  if(/\b(fireworks?|firework)\b/.test(c)) return { kind:'fireworks' };
  if(/\b(explore|look around|walk around|wander)\b/.test(c)) return { kind:'explore' };
  if(/\b(backflip|flip|spin|jump|wave|hug|high five)\b/.test(c) && cleaned.split(' ').length<=6) return { kind:'trick', v:(c.match(/\b(backflip|flip|spin|jump|wave|hug|high five)\b/)||[])[1] };
  var verb=GO_VERBS.test(c), id=null, len=0;
  Object.keys(PLACE_WORDS).forEach(function(k){ PLACE_WORDS[k].forEach(function(w){ if(c.indexOf(' '+w+' ')>-1 && w.length>len){ id=k; len=w.length; } }); });
  if(!id) return null;
  /* "where is your singapore office" stays a question; "singapore!" or "go to singapore" travels */
  var question=/\b(where|office|offices|address|located|location|hq|headquarters|price|cost|odoo|partner|company|hire|hiring|job|team|support)\b/.test(c);
  if(verb && !/\b(where)\b/.test(c)) return { kind:'place', v:id };
  if(!question && cleaned.split(' ').length<=3 && id!=='datacenter') return { kind:'place', v:id };
  return null;
}

/* conversation memory: the last topic, what Nexi just offered, what she said last */
var CTX = { last:null, lastAt:0, offer:null, said:{}, repeats:0, turns:0 };
function vary(key,list){ var i=CTX.said[key]; i=i==null?Math.floor(Math.random()*list.length):(i+1)%list.length; CTX.said[key]=i; return list[i]; }
function timeLine(){ var d=new Date(), h=d.getHours(), part=h<5?"Still up? It's":h<12?"Good morning! It's":h<18?"Good afternoon! It's":"Good evening! It's";
  return part+" "+d.toLocaleTimeString([], { hour:'numeric', minute:'2-digit' })+" on "+d.toLocaleDateString([], { weekday:'long', day:'numeric', month:'long' })+" where you are."; }
function greetLine(){ var h=new Date().getHours(); return h<5?"Hi, night owl!":h<12?"Good morning!":h<18?"Good afternoon!":"Good evening!"; }

