/* every place gets its own arrival line in the chat, plus chips that fit the place */
var PLACE_CHIPS = { studio:['odoo','ai','price'], singapore:['offices','partner','schedule'], philippines:['offices','careers','talk'], vietnam:['ai','offices','talk'], space:['hosting','ai','price'], snow:['inventory','support','talk'], datacenter:['hosting','security','integration'] };

/* ======================================================= TYPED MESSAGES
   Order: clean the text -> keyboard mash / contact details / links -> world
   commands -> small talk vs. the knowledge base (the stronger match wins)
   -> context retry ("how long does IT take" after a topic) -> site search
   -> closest topics. Nexi never dead-ends. */
var statusEl=$("#status"), STATUS0=statusEl?statusEl.textContent:"";
function setStatus(t){ if(statusEl) statusEl.textContent=t||STATUS0; }
function restoreStatus(){ var id=World.placeNow(); setStatus(id&&id!=="studio"?"Online · at "+World.placeInfo(id).name:STATUS0); }
function kbScore(cleaned){ var qt=toks(cleaned), qn=norm(cleaned); if(!qt.length) return { k:null, s:0, k2:null, s2:0 };
  var a=null,sa=0,b=null,sb=0; KB.forEach(function(k){ var s=scoreEntry(k,qt,qn); if(s>sa){ b=a; sb=sa; a=k; sa=s; } else if(s>sb){ b=k; sb=s; } });
  return { k:a, s:sa, k2:b, s2:sb }; }
function handleTyped(text){
  CTX.turns++;
  var raw=String(text).trim(), cleaned=clean(raw), shout=isShout(raw);
  var gib=isGibberish(cleaned,raw);
  if(gib){
    interrupt(); addUser(raw);
    if(gib==='emoji'){ mood("love"); say(vary("emoji",["Ooh, emoji! I speak fluent emoji. Beep boop ✨","Right back at you! What can I help with?"]),{ delay:600 }); chipsAfter(queue,"hello"); return; }
    mood("cat"); say(vary("gib",["Did a cat walk across your keyboard? I respect that, I'm part cat. Try asking about Odoo, AI or pricing!","Hmm, that looks like keyboard soup. Want to try again? Typos are fine, I'm good at them."]),{ delay:700 });
    chipsAfter(queue,"unknown"); return;
  }
  if(/[\w.+-]+@[\w-]+\.[\w.]+/.test(raw) || /(\+?\d[\d\s-]{7,}\d)/.test(raw)){
    interrupt(); addUser(raw); mood("shy");
    say("Ooh, contact details! I don't keep those in chat. Please pop them into the <b>Let's Talk</b> form and a consultant gets back to you.",{ html:true, delay:700, acts:[['talkform'],['wa']] });
    chipsAfter(queue,"talk"); CTX.offer={ kind:'talk' }; return;
  }
  if(/https?:\/\/|www\./i.test(raw)){
    interrupt(); addUser(raw); mood("think");
    say("I can't open links, sorry! But I know every page on technext.asia. Tell me what you're looking for.",{ delay:700 }); chipsAfter(queue,"unknown"); return;
  }
  var cmd=command(cleaned);
  if(cmd){ interrupt(); addUser(raw); runCommand(cmd); return; }

  var sm=smallMatch(cleaned), ks=kbScore(cleaned), u=understand(cleaned);
  if(sm && sm.s.id==='insult'){ interrupt(); addUser(raw); smallTalk(sm.s,shout); return; }
  var social=ks.k && (ks.k.id==='hello'||ks.k.id==='thanks');
  if(sm && (sm.s.short || !u || u.type==='site' || social || sm.score>=ks.s+.2)){
    if(sm.s.id==='yes' && CTX.offer && CTX.offer.kind==='tour'){ ask(byId(CTX.offer.v),raw); return; }
    interrupt(); addUser(raw); smallTalk(sm.s,shout); return;
  }
  /* "how long does it take?", "is that expensive?": borrow the last topic */
  var pron=/\b(it|that|this|they|them|those|these|one|there)\b/.test(' '+cleaned+' ');
  if(CTX.last && pron && (!u || u.type==='site' || ks.s<1.6) && LABEL[CTX.last]){
    var u2=understand(cleaned+' '+LABEL[CTX.last]); if(u2 && u2.type==='kb' && u2.k.id!==CTX.last) u=u2;
  }
  if(u && u.type==="tour"){ ask(u.q,raw); return; }
  interrupt(); addUser(raw);
  if(shout) mood("shout");
  if(u && u.type==="kb"){ answerKB(u.k,{ second:ks.k2 && ks.k2.id!==u.k.id && ks.s2>=1.6 && !ks.k2.goal ? ks.k2.id : null, shout:shout }); return; }
  if(u && u.type==="site"){ answerSite(u.pages); return; }
  answerUnknown(cleaned);
}
function smallTalk(s,shout){
  var line=vary(s.id,s.a), acts=(s.acts||[]).slice(), html=!!s.html, chips=null;
  if(line==="__TIME__"){ line=timeLine(); }
  if(line==="__YES__"){ var o=CTX.offer; CTX.offer=null;
    if(o && o.kind==='weather'){ doWeather(pick(["rain","snow","petals"]),true); return; }
    if(o && o.kind==='talk'){ say("Opening the form for you!",{ delay:300 }); try{ parent.postMessage({ tn:"nexi-talk" }, location.origin); }catch(e){} return; }
    if(o && o.kind==='place'){ doPlace(o.v,true); return; }
    if(o && o.kind==='kb'){ answerKB(kbById(o.v)); return; }
    line=vary("yes0",["Yay! What would you like to know?","Okay! Pick one below or just type."]); }
  if(line==="__MORE__"){
    var last=CTX.last, t=last&&TOPIC[last];
    if(t && t.tour && !asked[t.tour]){ CTX.offer=null; setTimeout(function(){ ask(byId(t.tour),"Show me"); },50); return; }
    var nxt=last&&(FOLLOW[last]||[]).filter(function(id){ return LABEL[id] && id!==last; })[0];
    if(nxt){ say(vary("more",["Here's the next bit!","Ooh, there's more. Related:","Let's go one level deeper:"]),{ delay:300 }); answerKB(kbById(nxt),{ quiet:true }); return; }
    line="Happy to! What would you like more on? Odoo, AI, websites or pricing?";
  }
  if(s.id==='weather') CTX.offer={ kind:'weather' };
  if(s.id==='robot'||s.id==='insult'||s.id==='sad') CTX.offer={ kind:'talk' };
  if(s.id==='bored'){ chips=['ai','website','odoo']; }
  if(s.id==='bye'){ acts.push(['quote']); }
  if(s.id==='sad'){ acts.push(['human']); }
  if(shout && s.id!=='insult') line="No need to shout, I'm right here! "+line;
  mood(shout && s.id!=='insult'?"shout":s.mood);
  if(s.mood==='love'||s.mood==='soft') World.blush(2);
  say(line,{ html:html, delay:650, acts:acts, sound:s.mood==='love'?"love":s.mood==='laugh'?"laugh":null });
  chipsAfter(queue,null,null,chips||(s.id==='can'?['odoo','ai','price']:FOLLOW.hello));
}
function runCommand(c){
  if(c.kind==='place'){ var P=World.placeInfo(c.v); if(World.placeNow()===c.v){ say(vary("here",["We're already here, silly! Look around.","Already here! Tap something nearby."]),{ delay:400 }); World.play("hop"); chipsAfter(queue,null,null,PLACE_CHIPS[c.v]); return; }
    say(vary("goto",["Hold on to your antenna!","Teleporting... 3, 2, 1!","Beam me there!"])+" Off to <b>"+esc(P.name)+"</b>.",{ html:true, delay:250 }); doPlace(c.v,false); return; }
  if(c.kind==='weather'){ doWeather(c.v,true); chipsAfter(queue,null,null,['ai','odoo','price']); return; }
  if(c.kind==='night'){ doNight(c.v,true); chipsAfter(queue,null,null,['odoo','ai','talk']); return; }
  if(c.kind==='party'){ doParty(true); chipsAfter(queue,null,null,['odoo','ai','talk']); return; }
  if(c.kind==='dance'){ World.routine("danceBreak"); Snd.play("dance"); say(vary("dance",["Music on! Watch these moves.","You asked for it. Robot dance!"]),{ delay:300 }); chipsAfter(queue,null,null,['odoo','ai','price']); return; }
  if(c.kind==='fireworks'){ World.fireworks(); say("Kaboom! Sparkles for you.",{ delay:400 }); chipsAfter(queue,null,null,['odoo','ai','price']); return; }
  if(c.kind==='explore'){ doExplore(true); chipsAfter(queue,null,null,PLACE_CHIPS[World.placeNow()]); return; }
  if(c.kind==='trick'){ var m={ backflip:"backflip", flip:"flip", spin:"spin", jump:"bigjump", wave:"wave", hug:"love", "high five":"clap" }[c.v]||"spin"; World.play(m); World.expr("star",1.6); World.word(pick(["TA-DA!","WHEE!","EASY!"])); say(vary("trick",["How was that?","Nailed it!","Ten out of ten, I'd say."]),{ delay:900 }); chipsAfter(queue,null,null,['odoo','ai','price']); return; }
}
function react(name){
  if(World.locked()){ World.defer(function(){ react(name); }); return; }
  if(REACT[name]) REACT[name](); else if(!World.routine(name)) World.play(name);
}
var REPEAT_LINES=["Asking again? Sure! Here it is:","Round two! Same answer, extra sparkle:","I love this one. Again:"];
var OPENERS=["Ooh, good one!","Easy peasy!","On it!","Beep boop, fetching that!","Great question!"];
function answerKB(k,o){
  if(!k) return; o=o||{};
  var t=TOPIC[k.id]||{}, my=turn, again=CTX.last===k.id;
  CTX.last=k.id; CTX.lastAt=Date.now(); CTX.offer=t.tour&&!asked[t.tour]?{ kind:'tour', v:t.tour }:null;
  setStatus("Thinking…");
  World.play("think"); World.expr("think",.8); Snd.play("think");
  setTimeout(function(){ if(my!==turn) return; if(again){ World.play("nod"); World.expr("content",1.2); World.word(pick(["AGAIN?","SURE!"])); } else react(t.react||"nod"); World.topic(t.icon); if(t.shot && !o.quiet) World.shot(t.shot); if(k.id==="partner") World.fact(); },800);
  var acts=(k.actions||[]).slice();
  var intro=again?pick(REPEAT_LINES):(t.intro?t.intro:pick(OPENERS));
  if(o.shout) intro="No need to shout, I'm right here! "+intro;
  var tail="";
  if(o.second && LABEL[o.second]) tail=' <span class="also">You also asked about <b>'+esc(LABEL[o.second].replace(/\?$/,''))+'</b>, tap it below.</span>';
  chipsAfter(say(esc(intro)+" "+k.a+tail,{ html:true, delay:o.quiet?300:800, acts:acts }),k.goal?"goal":k.id,t.tour,o.second?[o.second].concat((FOLLOW[k.goal?"goal":k.id]||FOLLOW.start).filter(function(x){ return x!==o.second; })):null);
}
function answerSite(pages){
  var top=pages[0], d=top.d||'', first=d.split('. ')[0], my=turn; if(first && first.length<d.length) first+='.';
  setStatus("Searching technext.asia…");
  World.play("think"); Snd.play("think"); setTimeout(function(){ if(my!==turn) return; react("nod"); World.topic("i_search"); },800);
  say(pick(["Let me look that up!","Found it on our site!","I dug through technext.asia for you."])+' Here\'s the page on <b>'+esc(cleanTitle(top.t))+'</b>. '+esc(first),{ html:true, delay:800, acts:pages.map(function(p){ return ['link',p.u,cleanTitle(p.t)]; }).concat([['wa']]) });
  chipsAfter(queue,"site");
}
function answerUnknown(text){
  mood("confused"); World.word(pick(["HMM?","BZZT?","HUH?"]));
  /* tolerance: offer the closest topics instead of a dead end */
  var qn=norm(text||""), qt=toks(text||""), near=[];
  if(qt.length) near=KB.filter(function(k){ return LABEL[k.id] && !k.goal; }).map(function(k){ return { id:k.id, s:scoreEntry(k,qt,qn) }; })
    .filter(function(x){ return x.s>=.3; }).sort(function(a,b){ return b.s-a.s; }).slice(0,2).map(function(x){ return x.id; });
  CTX.offer={ kind:'talk' };
  if(near.length){
    say(vary("unk1",["Hmm, I'm not 100% sure I got that. Did you mean one of these? Or ask my human teammates.","My circuits are 80% sure you mean one of these. Close? If not, my humans can help."]),{ delay:900, acts:[['wa'],['email']] });
    chipsAfter(queue,null,null,near.concat(['talk']));
  } else {
    say(vary("unk0",["Hmm, I don't have an answer for that one yet. My human teammates do! Message them on WhatsApp or email sales@technext.asia.","That one's outside my little robot brain. Try asking about Odoo, AI, websites or pricing, or ping my humans!"]),{ delay:900, acts:[['wa'],['email']] });
    chipsAfter(queue,"unknown");
  }
}

